<section class="card"><div class="section-heading"><div><h2>Kết nối đồng nghiệp</h2><p class="muted">Thông tin liên hệ trong công ty.</p></div></div><form method="get" class="filter-form" id="directory-search"><label class="sr-only" for="q">Tìm nhân viên</label><input id="q" name="q" maxlength="100" value="<?= e($q) ?>" placeholder="Tìm theo tên, phòng ban, email hoặc số máy lẻ…"><button id="search-directory" class="button">Tìm kiếm</button></form><div class="table-wrap"><table><thead><tr><th>Nhân viên</th><th>Phòng ban</th><th>Email</th><th>Máy lẻ</th><?php if(user()['role']==='hr'): ?><th>Thao tác</th><?php endif ?></tr></thead><tbody><?php foreach($list as $u): ?><tr><td><span class="person-cell"><span class="avatar small"><?= e(mb_substr($u['ho_ten'],0,1)) ?></span><?= e($u['ho_ten']) ?></span></td><td><?= e($u['ten_phong_ban']) ?></td><td><a href="mailto:<?= e($u['email']) ?>"><?= e($u['email']) ?></a></td><td><?= e($u['so_may_le']?:'—') ?></td><?php if(user()['role']==='hr'): ?><td><a class="button subtle" href="/directory?edit=<?= e($u['id']) ?>#directory-form">Sửa</a></td><?php endif ?></tr><?php endforeach ?><?php if(!$list): ?><tr><td colspan="5" class="empty">Không tìm thấy nhân viên phù hợp.</td></tr><?php endif ?></tbody></table></div></section>
<?php if($edit): ?><section class="card narrow" id="directory-form"><h2>Cập nhật danh bạ</h2><form method="post" class="form-stack"><?php csrf_field() ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php field('ho_ten','Họ tên',$edit['ho_ten'],'text',150); field('email','Email',$edit['email'],'email',190); field('so_may_le','Số máy lẻ',$edit['so_may_le'],'text',20,false); select_field('phong_ban_id','Phòng ban',array_column(departments(),'ten_phong_ban','id'),$edit['phong_ban_id']); ?><button id="save-directory" class="button">Lưu danh bạ</button></form></section><?php endif ?>
